        Page page = null;
        try {
            // browserManager를 통해 페이지 생성
            page = browserManager.newPage();
            if (page == null) {
                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
            }

            // 타임아웃 설정
